async function SYNTAX_CHECK() {
  let syn = 0, len = 0, num = 0, obj = 0, drive1 = false, drive2 = false, prep = 0, verb = 0;
  verb = get(g.P_ITBL, P_VERB);
  if (verb == 0) {
    (await NOT_IN_SENTENCE("any verbs"));
    return false;
  }
  syn = get(g.VERBS, 255 - verb);
  len = getb(syn, 0);
  syn = syn + 1;
  loop1: for (;;) {
    num = getb(syn, P_SBITS) & P_SONUMS;
    if (g.P_NCN > num) {
    } else if (!(num < 1) && (g.P_NCN == 0) && (((prep = get(g.P_ITBL, P_PREP1)) == 0) || (prep == getb(syn, P_SPREP1)))) {
      drive1 = syn;
    } else if (eq(getb(syn, P_SPREP1), get(g.P_ITBL, P_PREP1))) {
      if ((num == 2) && (g.P_NCN == 1)) {
        drive2 = syn;
      } else if (eq(getb(syn, P_SPREP2), get(g.P_ITBL, P_PREP2))) {
        await SYNTAX_FOUND(syn);
        return true;
      }
    }
    if (--len < 1) {
      if (drive1 || drive2) {
        break loop1;
      } else {
        await DONT_UNDERSTAND();
        return false;
      }
    } else {
      syn = syn + P_SYNLEN;
    }
  }
  if (drive1 && (obj = await GWIM(getb(drive1, P_SFWIM1), getb(drive1, P_SLOC1), getb(drive1, P_SPREP1)))) {
    put(g.P_PRSO, P_MATCHLEN, 1);
    put(g.P_PRSO, 1, obj);
    return await SYNTAX_FOUND(drive1);
  } else if (drive2 && (obj = await GWIM(getb(drive2, P_SFWIM2), getb(drive2, P_SLOC2), getb(drive2, P_SPREP2)))) {
    put(g.P_PRSI, P_MATCHLEN, 1);
    put(g.P_PRSI, 1, obj);
    return await SYNTAX_FOUND(drive2);
  } else if (verb == ACT.FIND) {
    tell("That's your problem!\n");
    return false;
  } else {
    if (g.WINNER == PLAYER) {
      await ORPHAN(drive1, drive2);
      tell("[Wh");
    } else {
      tell("[Your command wasn't complete. Next time, type wh");
    }
    if (verb == ACT.WALK || verb == ACT.GO) {
      tell("ere");
    } else if ((drive1 && eq(getb(drive1, P_SFWIM1), ACTORBIT)) || (drive2 && eq(getb(drive2, P_SFWIM2), ACTORBIT))) {
      tell("om");
    } else {
      tell("at");
    }
    if (g.WINNER == PLAYER) {
      tell(" do you want to ");
    } else {
      tell(" you want");
      await TPRINT(g.WINNER);
      tell(" to ");
    }
    await VERB_PRINT();
    if (drive2) {
      await CLAUSE_PRINT(P_NC1, P_NC1L);
    }
    g.P_END_ON_PREP = false;
    await PREP_PRINT(drive1 ? getb(drive1, P_SPREP1) : getb(drive2, P_SPREP2));
    if (g.WINNER == PLAYER) {
      g.P_OFLAG = true;
      tell("?]\n");
    } else {
      g.P_OFLAG = false;
      tell(".]\n");
    }
    return false;
  }
}

