async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0;
  len = get(tbl, P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = propSize(rmg) - 1;
    loop1: for (;;) {
      obj = getb(rmg, cnt);
      if (first(obj)) {
        await SEARCH_LIST(obj, tbl, P_SRCALL);
      }
      if (await THIS_IT$(obj)) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (rmg = getProp(g.HERE, P.THINGS)) {
    rmgl = get(rmg, 0);
    cnt = 0;
    loop2: for (;;) {
      if (g.P_NAM && !(g.P_NAM == get(rmg, cnt + 1))) {
      } else if (g.P_ADJ && !(g.P_ADJN == get(rmg, cnt + 2))) {
      } else if (g.P_NAM || g.P_ADJ) {
        g.LAST_PSEUDO_LOC = g.HERE;
        putProp(PSEUDO_OBJECT, P.ACTION, get(rmg, cnt + 3));
        foo = getPropAddr(PSEUDO_OBJECT, P.ACTION) - 5;
        rmg = get(rmg, cnt + 1);
        put(foo, 0, get(rmg, 0));
        put(foo, 1, get(rmg, 1));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop2;
      }
      cnt = cnt + 3;
      if (!(cnt < rmgl)) {
        break loop2;
      }
    }
  }
  if (eq(get(tbl, P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    g.P_SLOCBITS = obits;
    if (get(tbl, P_MATCHLEN) == 0) {
      if (isVerb(V.EXAMINE, V.CHASTISE, V.LOOK_INSIDE, V.FIND, V.FOLLOW, V.LEAVE, V.SEARCH, V.SMELL, V.ENTER, V.WALK_TO, V.WAIT_FOR, V.LOOK_ON)) {
        return await DO_SL(ROOMS, 1, 1);
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bits = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj))) {
        await OBJ_FOUND(obj, tbl);
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && first(obj) && (await SEE_INSIDE$(obj))) {
        await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP));
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function THIS_IT$(obj) {
  let syns = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (g.P_NAM && (!(syns = getPropAddr(obj, P.SYNONYM)) || !(await ZMEMQ(g.P_NAM, syns, div(propSize(syns), 2) - 1)))) {
    return false;
  } else if (g.P_ADJ && (!(syns = getPropAddr(obj, P.ADJECTIVE)) || !(await ZMEMQB(g.P_ADJ, syns, propSize(syns) - 1)))) {
    return false;
  } else if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  }
  return true;
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = get(tbl, P_MATCHLEN);
  put(tbl, ptr + 1, obj);
  return put(tbl, P_MATCHLEN, ptr + 1);
}

