async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return cnt + 1;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      if (cnt == 0) {
        return true;
      } else {
        return cnt;
      }
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm) {
  let ohere = 0, lit = false, ogwim = false;
  ohere = g.HERE;
  g.HERE = rm;
  if (hasFlag(rm, ONBIT)) {
    lit = true;
  } else if ((rm == ON_POOL_1) && (await LIT$(BOAT_DOCK))) {
    lit = true;
  } else if ((rm == ON_POOL_2) && (await LIT$(LEDGE))) {
    lit = true;
  } else {
    ogwim = g.P_GWIMBIT;
    g.P_GWIMBIT = ONBIT;
    put(g.P_MERGE, P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == PLAYER) && (loc(PLAYER) == rm)) {
        await DO_SL(PLAYER, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = ogwim;
  return lit;
}

async function PICK_ONE(frob, this_ = false) {
  let l = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  l = get(frob, 0);
  cnt = get(frob, 1);
  l = l - 1;
  frob = frob + 2;
  rfrob = frob + (cnt * 2);
  if (this_ && (cnt == 0)) {
    rnd = this_;
  } else {
    rnd = random(l - cnt);
  }
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == l) {
    cnt = 0;
  }
  put(frob, 0, cnt);
  return msg;
}

async function PICK_REMOVE(obj, frob) {
  let l = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0, robj = 0;
  l = get(frob, 0);
  cnt = get(frob, 1);
  l = l - 1;
  frob = frob + 2;
  rfrob = frob + ((cnt + 1) * 2);
  if (rnd = await ZMEMQ(obj, rfrob, l - cnt)) {
    rnd = rnd - 1;
    msg = get(rfrob, rnd);
    put(rfrob, rnd, get(rfrob, 0));
    put(rfrob, 0, msg);
    cnt = cnt + 1;
    if (cnt == l) {
      cnt = 0;
    }
    put(frob, 0, cnt);
    return msg;
  } else {
    return false;
  }
}

