async function FINISH(repeating = false) {
  let word = 0;
  crlf();
  if (!repeating) {
    await V_SCORE();
    crlf();
  }
  tell("Do you want to restart the story, restore a saved position, or quit?\n\n(Please type RESTART, RESTORE or QUIT.) >");
  await read(g.P_INBUF, g.P_LEXV);
  word = get(g.P_LEXV, 1);
  if (word == W.RESTAR) {
    await restart();
    await FAILED();
    return await FINISH(true);
  } else if (word == W.RESTOR) {
    if (await restore()) {
      return await SAY_OKAY();
    } else {
      await FAILED();
      return await FINISH(true);
    }
  } else if (word == W.QUIT || word == W.Q) {
    return await quit();
  } else {
    return await FINISH(true);
  }
}

