async function BOKS_BIG_ONE(t_obj) {
  if (!(eq(getProp(t_obj, P.VALUE), 0))) {
    g.SCORE = g.SCORE + getProp(t_obj, P.VALUE);
    putProp(t_obj, P.VALUE, 0);
    g.TREASURES_FOUND = g.TREASURES_FOUND + 1;
    if (g.TREASURES_FOUND == 10) {
      move(PEG_0, loc(t_obj));
      move(NOTE, loc(t_obj));
      if (!(t_obj == FINCH)) {
        move(t_obj, g.WINNER);
      }
      setFlag(t_obj, TOUCHBIT);
      clearFlag(t_obj, NDESCBIT);
      if (t_obj == RING) {
        tell("As you take");
        await TPRINT(g.PRSO);
        tell(", a small peg and a note drop out from under the model.\n");
        move(PEG_0, g.HERE);
        move(NOTE, g.HERE);
      } else {
        tell("As you ");
        printB(g.P_PRSA_WORD);
        await TPRINT(g.PRSO);
        tell(" you notice a wooden peg and a note ");
        if (t_obj == CORPSE_LINE || t_obj == GRATER || t_obj == PARKING_METER) {
          tell("behind");
        } else if (t_obj == FINCH) {
          tell("next to");
          await ARPRINT(FINCH);
          return true;
        } else {
          tell("beneath");
        }
        tell(" it.\n");
      }
      return true;
    }
    return true;
  } else {
    return false;
  }
}

