async function TELL_TIME() {
  let minutes = 0, hours = 0, pm = false;
  minutes = g.MOVES + 1260;
  if (minutes > 1439) {
    minutes = minutes - 1440;
  }
  hours = div(minutes, 60);
  if (hours > 11) {
    pm = true;
    hours = hours - 12;
  }
  if (hours == 0) {
    hours = 12;
  }
  tell(N(hours), ":");
  minutes = mod(minutes, 60);
  if (minutes < 10) {
    tell("0");
  }
  tell(N(minutes));
  if (pm) {
    tell(" pm");
    return true;
  } else {
    tell(" am");
    return true;
  }
}

