async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if (hasFlag(SKIS, WORNBIT) && !(g.PRSO == P.DOWN)) {
    tell("These are downhill skis, not cross-country skis!\n");
    return M_FATAL;
  } else if (!g.P_WALK_DIR) {
    if (g.PRSO) {
      (await PRESUMABLY_YOU_WANT_TO("walk to", g.PRSO));
      await PERFORM(V.WALK_TO, g.PRSO);
    } else {
      await V_WALK_AROUND();
    }
    return true;
  } else if (!(eq(loc(PLAYER), g.HERE))) {
    tell("You're not going anywhere while you're on");
    await TRPRINT(loc(PLAYER));
    return M_FATAL;
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(getb(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        await CANT_GO();
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = getb(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        await THIS_IS_IT(obj);
        return M_FATAL;
      } else {
        await ITS_CLOSED(obj);
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else {
    if (g.P_WALK_DIR == P.IN || g.P_WALK_DIR == P.OUT) {
      tell("Please use compass directions.\n");
      return true;
    } else {
      await CANT_GO();
      return M_FATAL;
    }
  }
}

