async function FILM_PROJECTOR_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It's a large, black, Simplex 70, 35mm ");
    await DPRINT(FILM_PROJECTOR);
    tell(". In the front it has a short lens. ");
    if (loc(LENS_CAP) == FILM_PROJECTOR) {
      tell("There's a lens cap on the lens. ");
    }
    tell("The ");
    await DPRINT(FILM_PROJECTOR);
    if (loc(FILM) == FILM_PROJECTOR) {
      tell(" has");
      await APRINT(FILM);
      tell(" in it, and");
    } else if (loc(CORPSE_LINE) == FILM_PROJECTOR) {
      tell(" has");
      await APRINT(CORPSE_LINE);
      tell(" in it, and");
    }
    tell(" is turned o");
    if (hasFlag(FILM_PROJECTOR, ONBIT)) {
      tell("n");
    } else {
      tell("ff");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.LAMP_ON) && !(hasFlag(FILM_PROJECTOR, ONBIT))) {
    tell("Immediately the projector begins to roll");
    setFlag(FILM_PROJECTOR, ONBIT);
    if ((loc(FILM) == FILM_PROJECTOR) || (loc(CORPSE_LINE) == FILM_PROJECTOR)) {
      if (loc(FILM) == FILM_PROJECTOR) {
        await QUEUE(I_FILM_DROP.id, 2);
      }
      tell(". The film starts to run through the projector");
      if (hasFlag(LENS_CAP, EVERYBIT /* LENS-CAP-OFF-BIT */)) {
        setFlag(SCREENING_ROOM, ONBIT);
        tell(" and a stream of colored light shoots out of the lens onto the screen in the screening room");
        if (loc(CORPSE_LINE) == FILM_PROJECTOR) {
          tell(".\n");
          await CORPSE_LINE_DEATH();
        }
      }
    } else {
      if (hasFlag(LENS_CAP, EVERYBIT /* LENS-CAP-OFF-BIT */)) {
        setFlag(SCREENING_ROOM, ONBIT);
        tell(". A stream of white light shoots out of the lens of");
        await TPRINT(FILM_PROJECTOR);
        tell(" onto the screen in the screening room");
      }
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await CANT_OPEN_CLOSE();
  } else if (isVerb(V.LAMP_OFF) && hasFlag(FILM_PROJECTOR, ONBIT)) {
    clearFlag(FILM_PROJECTOR, ONBIT);
    if (!(hasFlag(SLIDE_PROJECTOR, ONBIT))) {
      clearFlag(SCREENING_ROOM, ONBIT);
    }
    tell("You hear");
    await TPRINT(FILM_PROJECTOR);
    tell("'s whining trail off as it rolls to a stop.\n");
    return true;
  } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSI == FILM_PROJECTOR)) {
    if (!(g.PRSO == FILM || g.PRSO == CORPSE_LINE)) {
      return await WASTE_OF_TIME();
    } else if ((loc(FILM) == FILM_PROJECTOR) || (loc(CORPSE_LINE) == FILM_PROJECTOR)) {
      tell("You'll have to take");
      await TPRINT(first(FILM_PROJECTOR));
      tell(" out first.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CORPSE_LINE_DEATH() {
  tell("\nYour eyes are immediately drawn to the screen. ");
  if (hasFlag(SLIDE_PROJECTOR, ONBIT)) {
    tell("Although it's a little distorted by the slide projector, you");
  } else {
    tell("You");
  }
  return (await JIGS_UP(" quickly realize why \"A Corpse Line\" could never be released: From the back of a large theatre the camera slowly pans in. The camera moves forward and you are able to make out a dozen or more figures lying side-by-side on the stage in glittering top hats. Then the music starts and the figures rise to their feet. The camera is now close enough to see more detail. The figures are corpses, some badly decayed, clad in top hats. They begin to dance in unison as the music swells. For a moment you forget they are corpses and begin to enjoy their mastery of the art.\n\nThen the horror begins, just as it must have for Uncle Buddy. The line does a kick, and several legs fly into the audience. You feel your heart pounding as never before. The corpses, gripping each other's shoulders, turn at the same time and a half-dozen arms are pulled from their sockets. You can't seem to catch your breath. It's as if a pile of bricks were stacked on your chest. As the number ends, the corpses (what's left of them) remove their hats to take a bow. The camera moves in close as they bend over and you see the tops of their heads have been removed. You begin to shake uncontrollably, then you feel what seems like an explosion in your chest. The last thing you see is the corpses' brains plop onto the stage as they take their bow. You collapse."));
}

