async function BUCK_F(oarg = false) {
  if (oarg) {
    if (oarg == M_OBJDESC$) {
      return true;
    }
    if (!g.BUCK_TURNED$ && (g.SOUTH_JUNCTION_VISITS == 2)) {
      g.BUCK_DIR = P.SOUTH;
    }
    tell("\nA life-size statue of Buck Palace, one of the stars of Uncle Buddy's talent stables, stands here. He's holding a bazooka pointing ");
    await SAY_BUCK_DIR();
    tell(".");
    if (!g.BUCK_TURNED$ && (g.SOUTH_JUNCTION_VISITS == 2)) {
      tell(" Hmmm. It looks as if");
      await TPRINT(BUCK);
      tell(", has changed position.");
    }
    return true;
  } else if (isVerb(V.TURN)) {
    if (!g.PRSI) {
      tell("Next time, say which direction to turn it.\n");
      return true;
    } else if (!(g.PRSI == INTDIR)) {
      return false;
    } else if (g.P_DIRECTION == g.BUCK_DIR) {
      return (await ITS_ALREADY("turned that way"));
    } else {
      g.BUCK_DIR = g.P_DIRECTION;
      g.BUCK_TURNED$ = true;
      if ((g.STEPS_THROUGH_BUCK == 0) && (g.P_DIRECTION == P.WEST)) {
        g.STEPS_THROUGH_BUCK = 1;
      } else if ((g.STEPS_THROUGH_BUCK == 1) && (g.P_DIRECTION == P.EAST)) {
        g.STEPS_THROUGH_BUCK = 2;
      } else if ((g.STEPS_THROUGH_BUCK == 2) && (g.P_DIRECTION == P.NORTH)) {
        g.STEPS_THROUGH_BUCK = 3;
      } else {
        g.STEPS_THROUGH_BUCK = 0;
      }
      tell("You turn");
      await TPRINT(BUCK);
      tell(", to the ");
      await SAY_BUCK_DIR();
      if (g.STEPS_THROUGH_BUCK == 3) {
        tell(", and hear a click from off to the north");
        clearFlag(OAK_DOOR, LOCKEDBIT);
      }
      tell(".\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("It's pretty much what you would expect of a sculpture of Buck Palace. One hand is holding a pair of Uzi machine guns and his other hand is gripping a bazooka on his shoulder which he is pointing ");
    await SAY_BUCK_DIR();
    tell(". Several belts of ammunition crisscross his half-naked chest. He's wearing a double belt of grenades around his waist, and has a high-powered rifle stuck in one of his combat boots and a bayonet between his teeth. Of course Buck Palace, the fighting letter carrier, would not be complete without his government-issue mailbag over his shoulder. The statue is on a round, rotating pedestal, encircled by a compass rose.\n");
    return true;
  } else if (isVerb(V.PUSH, V.MOVE)) {
    tell("The ");
    await DPRINT(BUCK);
    tell(" turns slightly, then twists back with the bazooka pointing ");
    await SAY_BUCK_DIR();
    tell(".\n");
    return true;
  } else {
    return false;
  }
}

