async function GENERIC_CANDLE_F() {
  let num = 0, lit_candle = 0;
  if (isVerb(V.LAMP_OFF)) {
    num = 0;
    if (hasFlag(RED_CANDLE, FLAMEBIT) && (await VISIBLE$(RED_CANDLE))) {
      num = num + 1;
      lit_candle = RED_CANDLE;
    } else if (hasFlag(WHITE_CANDLE, FLAMEBIT) && (await VISIBLE$(WHITE_CANDLE))) {
      num = num + 1;
      lit_candle = WHITE_CANDLE;
    } else if (hasFlag(BLUE_CANDLE, FLAMEBIT) && (await VISIBLE$(BLUE_CANDLE))) {
      num = num + 1;
      lit_candle = BLUE_CANDLE;
    }
    if (num == 1) {
      return lit_candle;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CANDLE_F(candle) {
  let size = 0, feet = 0, i_candle = 0, candle_wax = 0;
  size = getProp(g.PRSO, P.SIZE);
  if (candle == RED_CANDLE) {
    feet = RED_FEET;
    i_candle = I_RED_CANDLE_BURN.id;
    candle_wax = RED_WAX;
  } else if (candle == WHITE_CANDLE) {
    feet = WHITE_FEET;
    i_candle = I_WHITE_CANDLE_BURN.id;
    candle_wax = WHITE_WAX;
  } else if (candle == BLUE_CANDLE) {
    feet = BLUE_FEET;
    i_candle = I_BLUE_CANDLE_BURN.id;
    candle_wax = BLUE_WAX;
  }
  if (isVerb(V.EXAMINE)) {
    if (size == 1) {
      await WAX_FEET(feet);
      return true;
    }
    tell("It's ");
    if (size < 10) {
      tell("what's left of ");
    }
    tell("a thin, wax statuette of a Hindu god, dressed in a long gown. ");
    if (size > 7) {
      tell("The foot-high god is holding up its ");
      if (g.PRSO == WHITE_CANDLE) {
        tell("lef");
      } else {
        tell("righ");
      }
      tell("t hand, showing ");
      if (g.PRSO == RED_CANDLE) {
        tell("three");
      } else if (g.PRSO == WHITE_CANDLE) {
        tell("seven");
      } else {
        tell("five");
      }
      tell(" fingers. ");
    }
    if (hasFlag(g.PRSO, ONBIT)) {
      tell("The wax statuette is lit, and a bit of wax is dripping down it");
    } else {
      if (size > 1) {
        tell("A wick is sticking up from ");
        if (size > 4) {
          tell("the top of the statuette");
        } else {
          tell("the little that remains of the statuette");
        }
      }
    }
    if ((size < 10) && (size > 1)) {
      tell(". The wax statuette has burned down to the god's ", S(get(g.CANDLE_DESC, size)));
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSI == candle)) {
    tell("You can't possibly do that.\n");
    return true;
  } else if (isVerb(V.LAMP_ON, V.BURN) && (g.PRSO == RED_CANDLE || g.PRSO == WHITE_CANDLE || g.PRSO == BLUE_CANDLE)) {
    if (await SET_FLAME_SOURCE()) {
      return true;
    }
    if (hasFlag(g.PRSI, FLAMEBIT)) {
      if (hasFlag(g.PRSO, FLAMEBIT)) {
        tell("It's already lit.\n");
        return true;
      } else if (size == 1) {
        tell("It's all used up. ");
        return await WAX_FEET(feet);
      } else {
        setFlag(g.PRSO, ONBIT);
        setFlag(g.PRSO, FLAMEBIT);
        clearFlag(g.PRSO, NDESCBIT);
        await QUEUE(i_candle, -1);
        move(candle_wax, candle);
        tell("You light");
        await TPRINT(g.PRSO);
        tell(" and a bit of wax begins to dribble down the god.\n");
        return true;
      }
    } else if (g.PRSI == RED_MATCH || g.PRSI == GREEN_MATCH || g.PRSI == RED_CANDLE || g.PRSI == BLUE_CANDLE || g.PRSI == WHITE_CANDLE) {
      tell("But");
      await TPRINT(g.PRSI);
      tell("'s not lit!\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (hasFlag(g.PRSO, ONBIT)) {
      return await BLOW_OUT_CANDLE(candle);
    } else {
      tell("The wax god isn't lit.\n");
      return true;
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await CANT_OPEN_CLOSE();
  } else if (isVerb(V.TAKE)) {
    clearFlag(g.PRSO, NDESCBIT);
    return false;
  } else {
    return false;
  }
}

async function CANDLE_BURN(candle, feet, i_candle) {
  let size = 0;
  putProp(candle, P.SIZE, getProp(candle, P.SIZE) - 1);
  size = getProp(candle, P.SIZE);
  if (size == 1) {
    if (await VISIBLE$(candle)) {
      crlf();
    }
    move(feet, loc(candle));
    await BLOW_OUT_CANDLE(candle);
    remove(candle);
    await DEQUEUE(i_candle);
  }
  if (size == 2) {
    if (candle == RED_CANDLE) {
      await QUEUE(I_RED_ALMOST_OUT.id, 5);
    } else if (candle == WHITE_CANDLE) {
      await QUEUE(I_WHITE_ALMOST_OUT.id, 5);
    } else if (candle == BLUE_CANDLE) {
      await QUEUE(I_BLUE_ALMOST_OUT.id, 5);
    }
  }
  if (!(await ACCESSIBLE$(candle))) {
    return false;
  } else if (size == 8 || size == 6 || size == 4 || size == 2) {
    tell("\nThe ");
    await DPRINT(candle);
    tell(" has burned down to the god's ", S(get(g.CANDLE_DESC, size)), ".\n");
    return true;
  } else {
    return false;
  }
}

