async function BLOW_OUT_CANDLE(candle, dont_tell = false) {
  let c_ = 0, feet = 0;
  clearFlag(candle, ONBIT);
  clearFlag(candle, FLAMEBIT);
  if (candle == RED_CANDLE) {
    feet = RED_FEET;
    if (c_ = await QUEUED$(I_RED_CANDLE_BURN.id)) {
      g.RED_MID_BURN = get(c_, C_TICK);
    } else {
      g.RED_MID_BURN = false;
    }
    await STOP_RED_BURNING();
  } else if (candle == WHITE_CANDLE) {
    feet = WHITE_FEET;
    if (c_ = await QUEUED$(I_WHITE_CANDLE_BURN.id)) {
      g.WHITE_MID_BURN = get(c_, C_TICK);
    } else {
      g.WHITE_MID_BURN = false;
    }
    await STOP_WHITE_BURNING();
  } else if (candle == BLUE_CANDLE) {
    feet = BLUE_FEET;
    if (c_ = await QUEUED$(I_BLUE_CANDLE_BURN.id)) {
      g.BLUE_MID_BURN = get(c_, C_TICK);
    } else {
      g.BLUE_MID_BURN = false;
    }
    await STOP_BLUE_BURNING();
  }
  if (!dont_tell && (await ACCESSIBLE$(candle))) {
    tell("The ");
    await DPRINT(candle);
    tell(" goes out.");
    if (eq(getProp(candle, P.SIZE), 1)) {
      tell(" ");
      await WAX_FEET(feet);
    } else if (g.PRSI == POND) {
      return true;
    } else {
      crlf();
    }
  }
  await SAY_IF_NOT_LIT();
  return true;
}

