async function FIREPLACE_GLOBAL_F() {
  if (isVerb(V.EXAMINE)) {
    if (g.HERE == FIREPLACE) {
      return await V_LOOK();
    } else {
      tell("You see a large, finely crafted brick fireplace.\n");
      return true;
    }
  } else if (isVerb(V.LOOK_INSIDE, V.SEARCH)) {
    if (g.HERE == LIVING_ROOM) {
      tell("You can't quite make out the inside of the fireplace from here.\n");
      return true;
    } else {
      tell("Look around you!\n");
      return true;
    }
  } else if (isVerb(V.ENTER, V.BOARD) && (g.HERE == LIVING_ROOM)) {
    return await GOTO(FIREPLACE);
  } else if (isVerb(V.REACH_IN)) {
    if (g.HERE == LIVING_ROOM) {
      tell("You reach in the fireplace and imagine a warm glow.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.CLIMB_UP) && (g.PRSI == FIREPLACE) && (g.HERE == FIREPLACE)) {
    return await DO_WALK(P.UP);
  } else if (isVerb(V.PUT)) {
    move(g.PRSO, FIREPLACE);
    tell("Done.\n");
    return true;
  } else {
    return false;
  }
}

