async function CHIMNEY_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It is your average chimney, made of bricks.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    if (g.HERE == ROOF_1) {
      tell("You see a few holes in the wall of");
      await TRPRINT(CHIMNEY);
      return true;
    } else {
      tell("You can't quite make out what's inside from here.\n");
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == CHIMNEY)) {
    if (g.HERE == FIREPLACE) {
      tell("You're at the bottom of the chimney!\n");
      return true;
    } else {
      tell("You drop");
      await TPRINT(g.PRSO);
      tell(" down the chimney.\n");
      if (g.HERE == ROOF_1 || g.HERE == CHIMNEY_1 || g.HERE == CHIMNEY_2) {
        if ((g.PRSO == RED_CANDLE || g.PRSO == WHITE_CANDLE || g.PRSO == BLUE_CANDLE) && hasFlag(g.PRSO, FLAMEBIT)) {
          await BLOW_OUT_CANDLE(g.PRSO);
        } else if ((g.PRSO == FINCH) || (await ULTIMATELY_IN$(FINCH, g.PRSO))) {
          await BREAK_FINCH(true);
        }
        return move(g.PRSO, FIREPLACE);
      } else {
        return move(g.PRSO, CHIMNEY_3);
      }
    }
  } else if (isVerb(V.ENTER)) {
    return await DO_WALK(P.IN);
  } else if (isVerb(V.CLIMB_UP)) {
    return await DO_WALK(P.UP);
  } else if (isVerb(V.CLIMB_DOWN)) {
    return await DO_WALK(P.DOWN);
  } else {
    return false;
  }
}

