async function V_PHONE() {
  if (!(await GLOBAL_IN$(PHONE, g.HERE))) {
    await THERE_DOESNT_SEEM();
    await APRINT(PHONE);
    tell(" here.\n");
    return true;
  } else if (g.PRSI && !(g.PRSI == PHONE)) {
    tell("Too bad");
    await TPRINT(g.PRSI);
    tell(" isn't a telephone.\n");
    return true;
  } else if (hasFlag(PHONE, EVERYBIT /* PHONE-DEAD-BIT */)) {
    tell("You don't hear a dial tone. The line is dead.\n");
    return true;
  } else if (g.PRSO == INTNUM) {
    if ((g.P_EXCHANGE > 999) || (g.P_NUMBER > 9999)) {
      tell("You dialed too many numbers. Remember what Aunt Hildegarde thought about guests making long distance calls!\n");
      return true;
    } else if (((g.P_EXCHANGE == 0) && (g.P_NUMBER == 0)) || ((g.P_EXCHANGE == 555) && (g.P_NUMBER == 1212)) || ((g.P_EXCHANGE == 0) && (g.P_NUMBER == 411))) {
      tell("You hear a lazy voice come on the line. \"You have reached the Malibu phone company. Our operator is busy now. Mellow out and try your call again later.\"\n");
      return true;
    } else if ((g.P_EXCHANGE == 0) && (g.P_NUMBER == 911)) {
      tell("A police officer answers the phone in mid-snore saying he'll send a car right over, then hangs up and goes back to sleep.\n");
      return true;
    } else if ((g.P_EXCHANGE == 492) && (g.P_NUMBER == 6000)) {
      tell("You hear voice talking at a fast pace trying to announce all the information necessary in 30 seconds. The voice says, \"Thank you for calling Infocom. We are closed now. Please call back during regular business hours, Monday through Friday, 9 a.m. to 6 p.m., Eastern Standard Time.\" Then the voice speeds up even more, giving information for technical problems and the special numbers to call. Finally you hear the voice take a deep breath and say, \"Have a nice (BEEP),\" and the message ends.\n");
      return true;
    } else if ((g.P_EXCHANGE == 576) && (g.P_NUMBER == 1851)) {
      tell("A nerdish voice answers");
      await TPRINT(PHONE);
      tell(" saying, \"Hello, this is Roy G. Biv, Computer Service and Repair. Our office is closed now. Please call back during our regular business hours.\"\n");
      return true;
    } else if ((g.P_EXCHANGE == 576) && (g.P_NUMBER == 3190)) {
      if (hasFlag(TOUPEE, EVERYBIT /* CARDS-RIGHT-BIT */)) {
        setFlag(PHONE, EVERYBIT /* PHONE-DEAD-BIT */);
        move(TOUPEE, HOPPER);
        tell("An answering machine comes on the line. It sounds like Aunt Hildegarde's voice saying, \"I can't come to the phone right now. I'm dead. Don't forget to look in the hopper.\" Then the line goes dead.\n");
        return true;
      } else {
        tell("You get a busy signal.\n");
        return true;
      }
    } else if (prob(60)) {
      tell("The ");
      await DPRINT(PHONE);
      tell(" rings and rings, but no one answers.\n");
      return true;
    } else {
      tell("The ");
      await DPRINT(PHONE);
      tell(" is answered, \"Hello? Hello? Hey, what is this, a crank call? You made my wife cry the last time you called, you pervert.\" You hear the receiver slammed down.\n");
      return true;
    }
  } else {
    tell("There's no sense in phoning");
    await ARPRINT(g.PRSO);
    return true;
  }
}

