async function I_SANDS_OF_TIME(x = 0) {
  let minutes = 0, cnt = 0, tcnt = 0, tnum = 0, follow_the_lawyer = false;
  minutes = g.MOVES + 1260;
  if (minutes == 1859) {
    x = 60;
    (await MICKEY_MOUSE(2, "hours"));
  } else if (minutes == 1919) {
    x = 30;
    (await MICKEY_MOUSE(1, "hour"));
  } else if (minutes == 1949) {
    x = 30;
    (await MICKEY_MOUSE(30, "minutes"));
  } else if (minutes == 1979) {
    if (g.HERE == FOYER || g.HERE == FRONT_PORCH || g.HERE == SOUTH_JUNCTION) {
      setFlag(LIVING_ROOM, ONBIT);
      follow_the_lawyer = true;
      tell("\n", S(g.OUT_OF_NOWHERE), "\"Ah, there you are. Let's go into the living room and talk,\" says the lawyer. You follow him to the living room.\n\n");
      await GOTO(LIVING_ROOM);
      crlf();
    }
    if (loc(PLAYER) == LIVING_ROOM) {
      if (!follow_the_lawyer) {
        tell("\n", S(g.OUT_OF_NOWHERE));
      }
      tell("\"Well, let's wrap this up quickly, I've got to be in court for the LaFlank divorce this afternoon,\" the lawyer snaps. He pauses for a moment, glancing around the room");
      tnum = get(g.TREASURE_TABLE, 0);
      loop1: for (;;) {
        if (++cnt > tnum) {
          break loop1;
        }
        x = get(g.TREASURE_TABLE, cnt);
        if (await VISIBLE$(x)) {
          tcnt = tcnt + 1;
        }
      }
      if (tcnt == 0) {
        tell(". \"Uhh, I don't see any 'treasures.'");
      } else if (tcnt == 10) {
        tell(" then at a small note pad in his hand. He congratulates you for finding all the \"treasures.\" \"But you didn't follow your aunt's instructions in the note.");
      } else {
        tell(" then at a small note pad in his hand. \"Uhh, I only count ", S(get(g.NUMWORDS, tcnt)), " 'treasure");
        if (!(tcnt == 1)) {
          tell("s");
        }
        tell("' here.");
      }
      tell(" I'm sorry, but you won't be inheriting Mrs. Burbank's estate after all,\" says the lawyer. He turns and leaves as his words echo in your head. Then you feel a sharp pain in your backside, as you kick yourself for not having ");
      if (tcnt == 10) {
        tell("followed the instructions in the note");
      } else if (g.TREASURES_FOUND == 10) {
        tell("brought all the \"treasures\" you found to the living room");
      } else if (g.TREASURES_FOUND == 0) {
        tell("found any of the \"treasures\"");
      } else {
        tell("found all the \"treasures\" in time");
      }
      tell(".\n");
    } else {
      tell("Your time is up! ");
      if (g.TREASURES_FOUND == 10) {
        tell("You did a good job by finding all the \"treasures,\" but you didn't meet the lawyer at 9 a.m.");
      } else if (g.TREASURES_FOUND > 0) {
        tell("You only found ", S(get(g.NUMWORDS, g.TREASURES_FOUND)), " of the ten \"treasures.\"");
      } else {
        tell("What a bozo! You didn't find any \"treasures.\" You're not fit to be fertilizer for the family tree! Are you sure you're a Burbank? I'd go on but there is only so much room on a disk.");
      }
      tell(" You can't help but think about how disappointed Aunt Hildegarde and Uncle Buddy would have been with you right now. Never mind your own disappointment of missing out on inheriting a fortune.");
    }
    g.MOVES = 720;
    await FINISH();
  }
  return await QUEUE(I_SANDS_OF_TIME.id, x);
}

