async function MATCH_F() {
  let waxed = 0;
  if (isVerb(V.EXAMINE)) {
    tell("It's the wooden, self-lighting variety of match. The ");
    await DPRINT(g.PRSO);
    if (hasFlag(g.PRSO, EVERYBIT /* WAXED-BIT */)) {
      tell(" head is coated with a thin layer of wax");
    } else if (hasFlag(g.PRSO, WETBIT)) {
      tell(" is wet");
    } else {
      tell(" is ");
      if (!(hasFlag(g.PRSO, ONBIT))) {
        tell("not ");
      }
      tell("lit");
    }
    tell(".\n");
    return true;
  } else if (isVerb(V.LAMP_ON, V.KILL)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      tell("You're not holding");
      await TRPRINT(g.PRSO);
      return true;
    } else if (hasFlag(g.PRSO, FLAMEBIT)) {
      tell("It's already lit.\n");
      return true;
    } else if (getProp(g.PRSO, P.MATCH_LIFE) == 0) {
      tell("You can't. It's all used up.\n");
      return true;
    } else if (hasFlag(g.PRSO, WETBIT)) {
      tell("It's wet. It won't light now.\n");
      return true;
    } else if (g.HERE == IN_POOL_1 || g.HERE == IN_POOL_2 || g.HERE == UNDERPASS_1 || g.HERE == UNDERPASS_2) {
      tell("Not even Uncle Buddy's best special effects men could light a match under water!\n");
      return true;
    } else if (g.HERE == ON_POOL_1 || g.HERE == ON_POOL_2 || g.HERE == INLET) {
      tell("You'd better find some dry land first.\n");
      return true;
    } else {
      await QUEUE(I_MATCH_BURN.id, -1);
      setFlag(g.PRSO, ONBIT);
      if (loc(WAX_COAT_1) == g.PRSO) {
        remove(WAX_COAT_1);
      } else if (loc(WAX_COAT_2) == g.PRSO) {
        remove(WAX_COAT_2);
      }
      setFlag(g.PRSO, FLAMEBIT);
      if (hasFlag(g.PRSO, EVERYBIT /* WAXED-BIT */)) {
        clearFlag(g.PRSO, EVERYBIT /* WAXED-BIT */);
        tell("The wax coating melts away as you light");
        await TRPRINT(g.PRSO);
      } else {
        tell("Okay,");
        await TPRINT(g.PRSO);
        tell(" is now lit.\n");
      }
      await NOW_LIT$();
      return true;
    }
  } else if (isVerb(V.LAMP_OFF)) {
    if (hasFlag(g.PRSO, ONBIT)) {
      return await BLOW_OUT_MATCH(g.PRSO);
    } else {
      tell("It's not lit.\n");
      return true;
    }
  } else if (isVerb(V.OPEN, V.CLOSE)) {
    return await CANT_OPEN_CLOSE();
  } else {
    return false;
  }
}

async function I_MATCH_BURN() {
  if (hasFlag(RED_MATCH, ONBIT)) {
    await MATCH_BURN(RED_MATCH);
  }
  if (hasFlag(GREEN_MATCH, ONBIT)) {
    return await MATCH_BURN(GREEN_MATCH);
  } else {
    return false;
  }
}

async function MATCH_BURN(obj) {
  if (getProp(obj, P.MATCH_LIFE) == 0) {
    return await BLOW_OUT_MATCH(obj, true);
  } else {
    return putProp(obj, P.MATCH_LIFE, getProp(obj, P.MATCH_LIFE) - 1);
  }
}

async function BLOW_OUT_MATCH(obj, add_cr = false) {
  clearFlag(obj, ONBIT);
  clearFlag(obj, FLAMEBIT);
  if (!(hasFlag(RED_MATCH, ONBIT)) && !(hasFlag(GREEN_MATCH, ONBIT))) {
    await DEQUEUE(I_MATCH_BURN.id);
  }
  if (await VISIBLE$(obj)) {
    if (add_cr) {
      crlf();
    }
    tell("The ");
    await DPRINT(obj);
    tell(" goes out, turns to ashes, falls to the ground and disappears.\n");
    await SAY_IF_NOT_LIT();
    return remove(obj);
  } else {
    return false;
  }
}

