async function BLOW_OUT_ALL_IN(obj, str = false) {
  if (!str) {
    (str = "");
  }
  for (;;) {
    if (!obj) {
      return true;
    } else {
      if (hasFlag(obj, FLAMEBIT)) {
        clearFlag(obj, FLAMEBIT);
        clearFlag(obj, ONBIT);
        tell(" The ");
        await DPRINT(obj);
        tell(" goes out", S(str), ".");
        if (obj == RED_CANDLE) {
          await STOP_RED_BURNING();
        } else if (obj == WHITE_CANDLE) {
          await STOP_WHITE_BURNING();
        } else if (obj == BLUE_CANDLE) {
          await STOP_BLUE_BURNING();
        } else if (obj == GREEN_MATCH || obj == RED_MATCH) {
          await DEQUEUE(I_MATCH_BURN.id);
        }
      }
      if (first(obj)) {
        await BLOW_OUT_ALL_IN(first(obj), str);
      }
      obj = next(obj);
    }
  }
}

