async function SKI_DOWN_STAIRS() {
  let candle = 0, match = 0;
  if (g.HERE == TOP_LANDING) {
    if (hasFlag(TOP_LANDING, EVERYBIT)) {
      clearFlag(TOP_LANDING, EVERYBIT);
      g.SCORE = g.SCORE + 10;
    }
    tell("You shuffle over the edge of the landing, and quickly gain momentum as you sail down the stairs.");
    if (await FIND_IN(PLAYER, FLAMEBIT)) {
      if ((loc(RED_CANDLE) == PLAYER) && hasFlag(RED_CANDLE, FLAMEBIT)) {
        ++candle;
        await BLOW_OUT_CANDLE(RED_CANDLE, true);
      }
      if ((loc(WHITE_CANDLE) == PLAYER) && hasFlag(WHITE_CANDLE, FLAMEBIT)) {
        ++candle;
        await BLOW_OUT_CANDLE(WHITE_CANDLE, true);
      }
      if ((loc(BLUE_CANDLE) == PLAYER) && hasFlag(BLUE_CANDLE, FLAMEBIT)) {
        ++candle;
        await BLOW_OUT_CANDLE(BLUE_CANDLE, true);
      }
      if (candle == 1 || candle == 2 || candle == 3) {
        tell(" The candle");
        if (candle == 2 || candle == 3) {
          tell("s");
        }
        tell(" in your hand blow");
        if (candle == 1) {
          tell("s");
        }
        tell(" out.");
      }
      if ((loc(RED_MATCH) == PLAYER) && hasFlag(RED_MATCH, FLAMEBIT)) {
        ++match;
        clearFlag(RED_MATCH, ONBIT);
        clearFlag(RED_MATCH, FLAMEBIT);
        remove(RED_MATCH);
        await DEQUEUE(I_MATCH_BURN.id);
      }
      if ((loc(GREEN_MATCH) == PLAYER) && hasFlag(GREEN_MATCH, FLAMEBIT)) {
        ++match;
        clearFlag(GREEN_MATCH, ONBIT);
        clearFlag(GREEN_MATCH, FLAMEBIT);
        remove(GREEN_MATCH);
        await DEQUEUE(I_MATCH_BURN.id);
      }
      if (match == 1 || match == 2) {
        tell(" The match");
        if (match == 2) {
          tell("s");
        }
        tell(" in your hand blow");
        if (match == 1) {
          tell("s");
        }
        tell(" out and you drop ");
        if (match == 1) {
          tell("it.");
        } else {
          tell("them.");
        }
      }
    }
    tell(" Ahead of you is the gap in the stairs. Racing into the gap, your skis bow slightly, but your forward momentum pulls you across the gap. You hit the landing at the bottom of the stairs but don't stop. You continue down a short flight of stairs then sail onto the sandy beach. You quickly stop with the drag of the sand and a feeble attempt to snow plow.\n\n");
    return true;
  } else {
    return false;
  }
}

