async function PROP_F() {
  let herman_thing = 0, player_thing = 0;
  herman_thing = first(HERMAN);
  player_thing = first(PLAYER);
  loop1: for (;;) {
    if (player_thing == 0) {
      break loop1;
    } else if (player_thing == TOUPEE || player_thing == MASK || player_thing == RING) {
      player_thing = next(player_thing);
    } else {
      break loop1;
    }
  }
  if (isVerb(V.TAKE)) {
    if (g.PRSO == herman_thing) {
      tell("You reach for");
      await TPRINT(herman_thing);
      tell(", but ");
      await DPRINT(HERMAN);
      tell(" twists away from you.\n");
      return true;
    } else if (player_thing) {
      tell("You're already armed with");
      await ARPRINT(player_thing);
      return true;
    } else {
      await PICK_REMOVE(g.PRSO, g.PROPS);
      return false;
    }
  } else if (isVerb(V.SHOOT, V.THROW) && (g.PRSI == HERMAN)) {
    await PERFORM(V.KILL, HERMAN, g.PRSO);
    return true;
  } else if (isVerb(V.KILL, V.CUT) && (g.PRSO == HERMAN)) {
    g.HERMAN_HITS = g.HERMAN_HITS + 1;
    if (g.HERMAN_DOWN) {
      await DEQUEUE(I_AUNT.id);
      tell("With the hate of all those summers of his bullying built up, you let Herman have it with");
      await TPRINT(player_thing);
      tell(", killing him. At the same time you hear a scream not unlike one you would hear in an Uncle Buddy movie. As the tone of the saw blade changes you realize your Aunt Hildegarde has just taken her final bow. You stand and cry for a few minutes remembering the good times with your aunt and wishing you had done more to save her.\n\nLater you find your way out of the prop vault. You go next door to Johnny's and call the police. Unfortunately it never occurred to you that with two dead bodies involved they wouldn't believe your story.\n");
      return await FINISH();
    } else if (g.HERMAN_HITS == 3) {
      g.HERMAN_DOWN = true;
      g.AUNT_COUNT = 6;
      await QUEUE(I_AUNT.id, 2);
      await DEQUEUE(I_HERMAN_ATTACK.id);
      tell("You ");
      if (player_thing == GUN) {
        tell("fire");
        await TPRINT(GUN);
        tell(" hitting him in the shoulder.");
      } else {
        tell("give it your best, striking Herman.");
      }
      tell(" He drops to the ground. (Hmm, guess that wasn't a prop after all.) Slowly, he starts to come to his feet. The saw blade is less than an inch from the blue-gray hairs of Aunt Hildegarde's head!\n");
      return true;
    } else {
      tell("You ");
      if (player_thing == GUN) {
        tell("fire");
        await TPRINT(GUN);
        tell(", blasting Herman with smooth and creamy whipped cream. You toss the gun away in disgust. It sails into the chute.\n");
      } else {
        tell("give it your best, striking Herman. The ");
        await DPRINT(player_thing);
        tell(" breaks into a hundred pieces. It was only a prop.\n");
      }
      return remove(player_thing);
    }
  } else {
    return false;
  }
}

