async function PUNCTUATION(paths) {
  if (paths == 4) {
    tell(", ");
  } else if (paths == 3) {
    tell(", ");
  } else if (paths == 2) {
    tell(" and ");
  } else {
    tell(".");
  }
  paths = paths - 1;
  return paths;
}

async function HEDGE_WALK(bit) {
  let steps = 0, mbits = 0;
  mbits = g.HM_BITS;
  for (;;) {
    if ((bit == X_N) && btst(mbits, X_N)) {
      g.HM_ROOM = g.HM_ROOM - 1;
    } else if ((bit == X_S) && btst(mbits, X_S)) {
      g.HM_ROOM = g.HM_ROOM + 1;
    } else if ((bit == X_E) && btst(mbits, X_E)) {
      g.HM_ROOM = g.HM_ROOM + 20;
    } else if ((bit == X_W) && btst(mbits, X_W)) {
      g.HM_ROOM = g.HM_ROOM - 20;
    } else {
      return steps;
    }
    steps = steps + 1;
    if (!(getb(g.HM_TABLE, g.HM_ROOM) == 0)) {
      return steps;
    } else {
      mbits = 15;
    }
  }
}

async function OBJECTS_TO_TABLE(sloc) {
  let tbl = 0, cnt = 0, f = first(HEDGE_MAZE), n_ = 0;
  remove(MAZE_HOLE);
  tbl = g.HEDGE_OBJECTS_TABLE;
  for (;;) {
    if (f) {
      n_ = next(f);
    } else {
      return true;
    }
    if (f == g.WINNER) {
    } else if (hasFlag(f, TAKEBIT)) {
      loop2: for (;;) {
        if (eq(get(tbl, cnt), 0)) {
          put(tbl, cnt, sloc);
          put(tbl, cnt + 1, f);
          cnt = cnt + 2;
          remove(f);
          break loop2;
        } else {
          cnt = cnt + 2;
        }
      }
    }
    f = n_;
  }
}

async function OBJECTS_TO_ROOM(sloc) {
  let tbl = 0, cnt = 0;
  tbl = g.HEDGE_OBJECTS_TABLE;
  for (;;) {
    if (!(cnt < HEDGE_OBJECT_TABLE_LENGTH)) {
      return true;
    } else if (eq(get(tbl, cnt), sloc)) {
      put(tbl, cnt, 0);
      move(get(tbl, cnt + 1), HEDGE_MAZE);
    }
    cnt = cnt + 2;
  }
}

